// Fan out: one item per account that can carry a buyer conversation. The
// credentials are per account — two Shopee shops are two different shops —
// so nothing below ever reuses another account's token.
const accounts = $input.first().json.accounts ?? [];
const CHAT = { shopee: 'shopee_chat', lazada: 'lazada_chat',
               tiktok: 'tiktok_dm', facebook: 'meta_dm', instagram: 'instagram_dm' };
return accounts
  .filter((a) => CHAT[a.platform] && a.sync_enabled)
  .map((a) => ({ json: {
    business_id: a.business_id,
    account_id: a.id,
    platform: a.platform,
    channel: CHAT[a.platform],
    label: a.label,
    // Only look as far back as the last sweep plus a minute of slack, so a
    // long-running poll cannot miss a message that arrived mid-run.
    since: new Date(Date.now() - 180000).toISOString(),
  } }));

// Shopee: sellerchat/get_conversation_list, then get_message per unread
// conversation. Signed over partner_id + path + timestamp + access_token +
// shop_id, which is Shopee's v2 common signature.
const crypto = require('crypto');
const creds = $('Get Account Credentials').item.json.credentials;
const item = $('One Account Each').item.json;
const host = creds.host || 'https://partner.shopeemobile.com';
const path = '/api/v2/sellerchat/get_conversation_list';
const ts = Math.floor(Date.now() / 1000);
const base = `${creds.partner_id}${path}${ts}${creds.access_token}${creds.shop_id}`;
const sign = crypto.createHmac('sha256', creds.partner_key).update(base).digest('hex');
const query = new URLSearchParams({
  partner_id: String(creds.partner_id), timestamp: String(ts), access_token: creds.access_token,
  shop_id: String(creds.shop_id), sign, direction: 'latest', type: 'all', page_size: '30',
});
return [{ json: { ...item, url: `${host}${path}?${query}`, vendor: 'shopee' } }];

// Lazada: /im/message/list under the open platform's sorted-parameter
// signature — app_secret, then every key and value in order, then app_secret.
const crypto = require('crypto');
const creds = $('Get Account Credentials').item.json.credentials;
const item = $('One Account Each').item.json;
const host = creds.host || 'https://api.lazada.com.ph/rest';
const path = '/im/message/list';
const params = {
  app_key: creds.app_key, access_token: creds.access_token,
  timestamp: String(Date.now()), sign_method: 'sha256',
  page_size: '30',
};
const sorted = Object.keys(params).sort().map((k) => k + params[k]).join('');
const sign = crypto.createHmac('sha256', creds.app_secret)
  .update(path + sorted).digest('hex').toUpperCase();
const query = new URLSearchParams({ ...params, sign });
return [{ json: { ...item, url: `${host}${path}?${query}`, vendor: 'lazada' } }];

// TikTok Shop: customer_service/202309/conversations, signed over the sorted
// query wrapped in the app secret.
const crypto = require('crypto');
const creds = $('Get Account Credentials').item.json.credentials;
const item = $('One Account Each').item.json;
const host = creds.host || 'https://open-api.tiktokglobalshop.com';
const path = '/customer_service/202309/conversations';
const params = {
  app_key: creds.app_key, shop_cipher: creds.shop_cipher,
  timestamp: String(Math.floor(Date.now() / 1000)), version: '202309', page_size: '30',
};
const sorted = Object.keys(params).sort().map((k) => k + params[k]).join('');
const base = creds.app_secret + path + sorted + creds.app_secret;
const sign = crypto.createHmac('sha256', creds.app_secret).update(base).digest('hex');
const query = new URLSearchParams({ ...params, sign });
return [{ json: { ...item, url: `${host}${path}?${query}`,
                  access_token: creds.access_token, vendor: 'tiktok' } }];

// A channel nobody has written a poller for. Said out loud rather than
// dropped, because an inbox that silently misses a buyer is worse than one
// that admits it cannot read a platform.
const item = $('One Account Each').item.json;
return [{ json: { ...item, skipped: true,
  error: `No chat poller is wired up for ${item.platform} yet.` } }];

// Every marketplace shapes a conversation differently. Flatten them into the
// one shape the inbox stores, keeping the marketplace's own thread id so a
// reply goes back to the same conversation rather than opening a new one.
const item = $('One Account Each').item.json;
const body = $input.item.json;
const out = [];

const push = (external_id, buyer_name, buyer_handle, text, message_external_id) => {
  const trimmed = String(text ?? '').trim();
  if (!trimmed) return;
  out.push({ json: {
    business_id: item.business_id, account_id: item.account_id,
    channel: item.channel, external_id: String(external_id),
    buyer_name: buyer_name || 'Buyer', buyer_handle: buyer_handle || null,
    body: trimmed.slice(0, 4000),
    message_external_id: message_external_id ? String(message_external_id) : null,
  } });
};

if (item.platform === 'shopee') {
  for (const c of body?.response?.conversation ?? []) {
    if (!c.unread_count) continue;
    push(c.conversation_id, c.to_name, c.to_id, c.latest_message_content?.text, c.last_message_id);
  }
} else if (item.platform === 'lazada') {
  for (const m of body?.data?.messages ?? []) {
    if (m.from_account_type === 1) continue;   // 1 is the seller: our own line
    push(m.session_id, m.from_nick_name, m.from_account_id, m.content?.txt, m.message_id);
  }
} else if (item.platform === 'tiktok') {
  for (const c of body?.data?.conversations ?? []) {
    const last = c.latest_message;
    if (!last || last.sender?.role === 'SELLER') continue;
    push(c.id, c.participants?.[0]?.nickname, c.participants?.[0]?.im_user_id,
         last.content, last.id);
  }
}
return out;

// The prompt is built from the skills this desk actually has switched on, so
// turning one off in the dashboard really does change what the model is asked
// to do rather than only what the screen says.
const checkout = $('Claim The CRM Desk').item.json;
const thread = $('Read The Thread').item.json;
const skills = (checkout.skills ?? []).map((s) => `- ${s.name}: ${s.summary}`).join('\n');
const history = (thread.messages ?? [])
  .map((m) => `${m.direction === 'IN' ? 'Buyer' : 'Us'}: ${m.body}`)
  .join('\n');
const c = thread.conversation ?? {};

const prompt = [
  `You answer buyers for ${c.account_label ?? 'our shop'} on ${c.channel}.`,
  'What this desk is for:', skills || '- answering buyers politely and accurately',
  '',
  'Rules:',
  '- Write one short reply, in the language the buyer used.',
  '- Philippine pesos, written as PHP 1,250.',
  '- Never promise stock, a delivery date or a discount you were not told about.',
  '- If you do not know, say you will check — do not invent an answer.',
  '- Never offer to call them: this channel has no voice, only chat.',
  '',
  c.product_name ? `They seem to be asking about: ${c.product_name} (${c.product_sku}).` : '',
  '', 'The conversation so far:', history,
  '', 'Write only the reply.',
].filter(Boolean).join('\n');

return [{ json: { prompt, conversation_id: c.id, business_id: c.business_id,
                  agent_id: checkout.agent.id } }];

// Two kinds come through here: a reply to a buyer, and the Payment Collector's
// nudge about an order nobody has paid for. Both are a line of text going to a
// customer, so both arrive with an approval id behind them.
const body = $input.first().json.body;
const payload = body.payload ?? {};
const conversation = body.conversation ?? null;
const order = body.order ?? null;

// A chase has an order but may have no thread yet; answering on the order's
// own conversation is better than opening a second one.
const channel = payload.channel || conversation?.channel || 'email';
return [{ json: {
  approval_id: body.approval_id,
  business_id: body.business_id,
  conversation_id: payload.conversation_id ?? conversation?.id ?? null,
  account_id: payload.account_id ?? conversation?.account_id ?? null,
  external_id: conversation?.external_id ?? null,
  recipient: payload.recipient ?? conversation?.buyer_handle ?? order?.buyer_name ?? null,
  channel,
  platform: channel.replace(/_(chat|dm)$/, '').replace('meta', 'facebook'),
  text: String(payload.draft ?? '').trim(),
  kind: payload.type,
} }];

// Shopee: sellerchat/send_message, same v2 signature as the poller.
const crypto = require('crypto');
const creds = $('Credentials To Send With').item.json.credentials;
const msg = $('What Was Approved').item.json;
if (!creds?.access_token) {
  return [{ json: { ...msg, failed: true, error: 'SHOPEE access_token is not set for this shop' } }];
}
const host = creds.host || 'https://partner.shopeemobile.com';
const path = '/api/v2/sellerchat/send_message';
const ts = Math.floor(Date.now() / 1000);
const base = `${creds.partner_id}${path}${ts}${creds.access_token}${creds.shop_id}`;
const sign = crypto.createHmac('sha256', creds.partner_key).update(base).digest('hex');
const query = new URLSearchParams({
  partner_id: String(creds.partner_id), timestamp: String(ts),
  access_token: creds.access_token, shop_id: String(creds.shop_id), sign });
return [{ json: { ...msg, url: `${host}${path}?${query}`, method: 'POST',
  payload: { to_id: Number(msg.recipient), message_type: 'text',
             content: { text: msg.text } } } }];

// Lazada: /im/message/send.
const crypto = require('crypto');
const creds = $('Credentials To Send With').item.json.credentials;
const msg = $('What Was Approved').item.json;
if (!creds?.access_token) {
  return [{ json: { ...msg, failed: true, error: 'LAZADA access_token is not set for this shop' } }];
}
const host = creds.host || 'https://api.lazada.com.ph/rest';
const path = '/im/message/send';
const params = { app_key: creds.app_key, access_token: creds.access_token,
                 timestamp: String(Date.now()), sign_method: 'sha256',
                 session_id: String(msg.external_id ?? ''),
                 template_id: '1', txt: msg.text };
const sorted = Object.keys(params).sort().map((k) => k + params[k]).join('');
const sign = crypto.createHmac('sha256', creds.app_secret)
  .update(path + sorted).digest('hex').toUpperCase();
return [{ json: { ...msg, url: `${host}${path}?${new URLSearchParams({ ...params, sign })}`,
  method: 'POST', payload: {} } }];

// TikTok Shop: customer_service/202309/messages.
const crypto = require('crypto');
const creds = $('Credentials To Send With').item.json.credentials;
const msg = $('What Was Approved').item.json;
if (!creds?.access_token || !creds?.shop_cipher) {
  return [{ json: { ...msg, failed: true,
    error: 'TIKTOK access_token or shop_cipher is not set for this shop' } }];
}
const host = creds.host || 'https://open-api.tiktokglobalshop.com';
const path = `/customer_service/202309/conversations/${msg.external_id}/messages`;
const body = JSON.stringify({ type: 'TEXT', content: JSON.stringify({ content: msg.text }) });
const params = { app_key: creds.app_key, shop_cipher: creds.shop_cipher,
                 timestamp: String(Math.floor(Date.now() / 1000)), version: '202309' };
const sorted = Object.keys(params).sort().map((k) => k + params[k]).join('');
const base = creds.app_secret + path + sorted + body + creds.app_secret;
const sign = crypto.createHmac('sha256', creds.app_secret).update(base).digest('hex');
return [{ json: { ...msg, url: `${host}${path}?${new URLSearchParams({ ...params, sign })}`,
  method: 'POST', payload: JSON.parse(body), access_token: creds.access_token } }];

// Meta: the Send API, on the page token this account holds.
const creds = $('Credentials To Send With').item.json.credentials;
const msg = $('What Was Approved').item.json;
if (!creds?.page_access_token) {
  return [{ json: { ...msg, failed: true,
    error: 'META page_access_token is not set for this page' } }];
}
return [{ json: { ...msg,
  url: `https://graph.facebook.com/v21.0/me/messages?access_token=${creds.page_access_token}`,
  method: 'POST',
  payload: { recipient: { id: msg.recipient }, messaging_type: 'RESPONSE',
             message: { text: msg.text } } } }];

// Nobody wired a sender for this channel. The reply is reported as failed with
// the reason, so the thread goes back to OPEN and somebody can answer by hand
// — rather than the approval looking sent and the buyer hearing nothing.
const msg = $('What Was Approved').item.json;
return [{ json: { ...msg, failed: true,
  error: `No sender is wired up for ${msg.channel} yet.` } }];
